const COLORS = {
  blueDeep: '#12384C',
  blue: '#1D6FA0',
  blueSoft: '#E4EEF3',
  greenDeep: '#1F5C46',
  green: '#3E9B70',
  greenSoft: '#E5F1EA',
  paper: '#FAF8F3',
  ink: '#182420',
  muted: '#5B6B66',
  line: '#DDD6C6',
};

