/* ------------------------------------------------------------------ */
/*  UI HELPERS                                                         */
/* ------------------------------------------------------------------ */

function Pill({ children, tone = 'green' }) {
  const bg = tone === 'green' ? COLORS.greenSoft : COLORS.blueSoft;
  const fg = tone === 'green' ? COLORS.greenDeep : COLORS.blueDeep;
  return (
    <span
      className="text-xs font-medium px-3 py-1 rounded-full inline-block"
      style={{ backgroundColor: bg, color: fg }}
    >
      {children}
    </span>
  );
}

function SectionHeading({ children, id }) {
  return (
    <h2 id={id} className="cnrs-display text-3xl md:text-4xl font-semibold mb-8" style={{ color: COLORS.blueDeep }}>
      {children}
    </h2>
  );
}

function AdminBar({ label, onAdd }) {
  return (
    <div className="flex justify-between items-center mb-6 pb-4" style={{ borderBottom: `1px solid ${COLORS.line}` }}>
      <span className="text-sm font-medium" style={{ color: COLORS.green }}>
        Mode administrateur — {label}
      </span>
      <button
        onClick={onAdd}
        className="flex items-center gap-2 text-sm font-semibold px-4 py-2 rounded-lg text-white transition"
        style={{ backgroundColor: COLORS.green }}
      >
        <Plus size={16} /> Ajouter
      </button>
    </div>
  );
}

function ItemAdminControls({ onEdit, onDelete }) {
  return (
    <div className="flex gap-2 mt-3">
      <button
        onClick={onEdit}
        className="flex items-center gap-1 text-xs font-medium px-3 py-1.5 rounded-md border transition"
        style={{ borderColor: COLORS.blue, color: COLORS.blue }}
      >
        <Pencil size={13} /> Modifier
      </button>
      <button
        onClick={onDelete}
        className="flex items-center gap-1 text-xs font-medium px-3 py-1.5 rounded-md border transition"
        style={{ borderColor: '#B3453B', color: '#B3453B' }}
      >
        <Trash2 size={13} /> Supprimer
      </button>
    </div>
  );
}

const inputClass = "w-full px-4 py-2 rounded-lg border text-sm focus:outline-none focus:ring-2";
const inputStyle = { borderColor: COLORS.line, backgroundColor: '#FFFFFF', color: COLORS.ink };

/* ------------------------------------------------------------------ */
/*  MAIN COMPONENT                                                     */
/* ------------------------------------------------------------------ */

export default function CenaressesWebsite() {
  const [currentPage, setCurrentPage] = useState('home');
  const [menuOpen, setMenuOpen] = useState(false);

  const [showContactForm, setShowContactForm] = useState(false);
  const [showAppointmentForm, setShowAppointmentForm] = useState(false);

  const [isAdmin, setIsAdmin] = useState(false);
  const [adminToken, setAdminToken] = useState(null);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPasswordInput, setAdminPasswordInput] = useState('');
  const [adminError, setAdminError] = useState('');
  const [adminBusy, setAdminBusy] = useState(false);

  const [content, setContent] = useState(DEFAULT_CONTENT);
  const [loading, setLoading] = useState(true);
  const [saveError, setSaveError] = useState('');

  // formType: 'project' | 'publication' | 'team' | 'news' | null
  const [formType, setFormType] = useState(null);
  const [editingItem, setEditingItem] = useState(null);

  /* ---- Chargement initial depuis le backend ---- */
  useEffect(() => {
    (async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/content`);
        if (!res.ok) throw new Error('Réponse serveur invalide');
        const data = await res.json();
        setContent(data);
        setSaveError('');
      } catch (err) {
        // Le backend n'est pas joignable : le site reste consultable
        // avec le contenu par défaut, mais l'édition sera indisponible.
        setContent(DEFAULT_CONTENT);
        setSaveError("Impossible de joindre le serveur de contenu. Le site affiche des données par défaut.");
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  async function saveContent(next) {
    const previous = content;
    setContent(next); // mise à jour optimiste
    try {
      const res = await fetch(`${API_BASE_URL}/api/content`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${adminToken}`,
        },
        body: JSON.stringify(next),
      });
      if (!res.ok) throw new Error('Échec de la sauvegarde');
      setSaveError('');
    } catch (err) {
      setContent(previous); // on annule si la sauvegarde échoue
      setSaveError("La modification n'a pas pu être enregistrée. Réessayez.");
    }
  }

  /* ---- Authentification admin (via le backend) ---- */
  async function handleAdminLogin(e) {
    e.preventDefault();
    setAdminBusy(true);
    setAdminError('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/admin/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password: adminPasswordInput }),
      });
      if (!res.ok) throw new Error('unauthorized');
      const { token } = await res.json();
      setAdminToken(token);
      setIsAdmin(true);
      setShowAdminLogin(false);
      setAdminPasswordInput('');
    } catch (err) {
      setAdminError('Mot de passe incorrect ou serveur injoignable.');
    } finally {
      setAdminBusy(false);
    }
  }

  async function handleAdminLogout() {
    try {
      await fetch(`${API_BASE_URL}/api/admin/logout`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${adminToken}` },
      });
    } catch (err) {
      // pas grave si la requête échoue, on déconnecte côté client de toute façon
    }
    setIsAdmin(false);
    setAdminToken(null);
  }

  /* ---- CRUD générique ---- */
  function openAddForm(type) {
    setFormType(type);
    setEditingItem(null);
  }
  function openEditForm(type, item) {
    setFormType(type);
    setEditingItem(item);
  }
  function closeForm() {
    setFormType(null);
    setEditingItem(null);
  }

  const collectionKey = { project: 'projects', publication: 'publications', team: 'team', news: 'news' };

  function handleFormSubmit(e) {
    e.preventDefault();
    const fd = new FormData(e.target);
    const key = collectionKey[formType];
    let item = { id: editingItem ? editingItem.id : `${formType}-${Date.now()}` };

    if (formType === 'project') {
      item = { ...item, title: fd.get('title'), description: fd.get('description'), icon: fd.get('icon') || '📁', status: fd.get('status') };
    } else if (formType === 'publication') {
      item = { ...item, title: fd.get('title'), authors: fd.get('authors'), year: fd.get('year'), type: fd.get('type') };
    } else if (formType === 'team') {
      item = { ...item, name: fd.get('name'), role: fd.get('role'), speciality: fd.get('speciality'), icon: fd.get('icon') || '👤' };
    } else if (formType === 'news') {
      item = { ...item, title: fd.get('title'), date: fd.get('date'), content: fd.get('content') };
    }

    const list = content[key] || [];
    const nextList = editingItem
      ? list.map((it) => (it.id === item.id ? item : it))
      : [...list, item];

    saveContent({ ...content, [key]: nextList });
    closeForm();
  }

  function handleDelete(type, id) {
    if (!window.confirm('Supprimer cet élément ?')) return;
    const key = collectionKey[type];
    const nextList = content[key].filter((it) => it.id !== id);
    saveContent({ ...content, [key]: nextList });
  }

  function handleContactSubmit(e) {
    e.preventDefault();
    alert('Votre message a été envoyé avec succès. Nous vous répondrons bientôt.');
    setShowContactForm(false);
  }

  function handleAppointmentSubmit(e) {
    e.preventDefault();
    alert('Votre demande de rendez-vous a été enregistrée.');
    setShowAppointmentForm(false);
  }

  const pages = ['home', 'about', 'projects', 'publications', 'team', 'news', 'resources'];
  const pageLabels = {
    home: 'Accueil', about: 'À propos', projects: 'Projets', publications: 'Publications',
    team: 'Équipe', news: 'Actualités', resources: 'Ressources',
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center cnrs-root" style={{ backgroundColor: COLORS.paper }}>
        {FONTS}
        <div className="flex items-center gap-3" style={{ color: COLORS.blueDeep }}>
          <Loader2 className="animate-spin" size={20} />
          <span>Chargement du site…</span>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen cnrs-root" style={{ backgroundColor: COLORS.paper }}>
      {FONTS}

      {/* Signature animée : les couleurs du logo qui défilent en continu */}
      <div className="h-1 cnrs-flow-bar" />

      {/* NAVIGATION */}
      <nav className="sticky top-0 z-40" style={{ backgroundColor: COLORS.blueDeep }}>
        <div className="max-w-6xl mx-auto px-5 py-4">
          <div className="flex justify-between items-center">
            <button onClick={() => setCurrentPage('home')} className="flex items-center gap-3 text-left">
              <div className="w-11 h-11 rounded-full flex items-center justify-center flex-shrink-0 bg-white p-0.5">
                <img src={LOGO_DATA_URI} alt="Logo CENARESSES" className="w-full h-full rounded-full object-cover" />
              </div>
              <div>
                <p className="cnrs-display text-white font-semibold leading-tight">CENARESSES</p>
                <p className="text-xs leading-tight" style={{ color: '#B9CBD3' }}>N'Djaména, Tchad</p>
              </div>
            </button>

            <div className="hidden md:flex gap-7">
              {pages.map((item) => (
                <button
                  key={item}
                  onClick={() => setCurrentPage(item)}
                  className="text-sm font-medium pb-1.5 transition relative"
                  style={{ color: currentPage === item ? '#FFFFFF' : '#AFC4CD' }}
                >
                  {pageLabels[item]}
                  {currentPage === item && (
                    <span className="absolute left-0 right-0 -bottom-0.5 h-0.5 rounded-full cnrs-flow-bar" />
                  )}
                </button>
              ))}
            </div>

            <div className="flex gap-3 items-center">
              {isAdmin ? (
                <button
                  onClick={handleAdminLogout}
                  className="hidden sm:flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-semibold text-white transition"
                  style={{ backgroundColor: COLORS.green }}
                >
                  <LogOut size={14} /> Quitter l'espace admin
                </button>
              ) : (
                <button
                  onClick={() => setShowAdminLogin(true)}
                  title="Espace administrateur"
                  className="hidden sm:flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-medium transition"
                  style={{ color: '#AFC4CD', border: '1px solid #2E5266' }}
                >
                  <ShieldCheck size={14} /> Administration
                </button>
              )}
              <button className="md:hidden text-white" onClick={() => setMenuOpen(!menuOpen)}>
                {menuOpen ? <X /> : <Menu />}
              </button>
            </div>
          </div>

          {menuOpen && (
            <div className="md:hidden mt-4 space-y-1 pb-3">
              {pages.map((item) => (
                <button
                  key={item}
                  onClick={() => { setCurrentPage(item); setMenuOpen(false); }}
                  className="block w-full text-left px-3 py-2 rounded text-sm font-medium"
                  style={{ color: currentPage === item ? '#FFFFFF' : '#AFC4CD' }}
                >
                  {pageLabels[item]}
                </button>
              ))}
              <button
                onClick={() => { isAdmin ? handleAdminLogout() : setShowAdminLogin(true); setMenuOpen(false); }}
                className="block w-full text-left px-3 py-2 rounded text-sm font-medium"
                style={{ color: COLORS.green }}
              >
                {isAdmin ? "Quitter l'espace admin" : 'Administration'}
              </button>
            </div>
          )}
        </div>
      </nav>

      {saveError && (
        <div className="max-w-6xl mx-auto px-5 pt-4">
          <div className="flex items-center gap-2 text-sm px-4 py-3 rounded-lg" style={{ backgroundColor: '#FBEAE8', color: '#B3453B' }}>
            <AlertCircle size={16} /> {saveError}
          </div>
        </div>
      )}

      {/* CONTENU PRINCIPAL */}
      <div className="max-w-6xl mx-auto px-5 py-14">

        {/* ---------------- HOME ---------------- */}
        {currentPage === 'home' && (
          <div className="space-y-20">
            <div className="grid md:grid-cols-5 gap-10 items-start">
              <div className="md:col-span-3 space-y-6">
                <Pill tone="green">Recherche appliquée · Tchad</Pill>
                <h1 className="cnrs-display text-4xl md:text-5xl font-semibold leading-tight" style={{ color: COLORS.blueDeep }}>
                  Des données probantes pour des politiques de santé et de développement plus efficaces
                </h1>
                <p className="text-lg leading-relaxed" style={{ color: COLORS.muted }}>
                  Le CENARESSES est un centre de recherche basé au Tchad, spécialisé dans les sciences sociales,
                  environnementales et de la santé. Nous travaillons aux côtés des institutions publiques et de
                  leurs partenaires pour transformer les données en décisions.
                </p>
                <div className="flex flex-wrap gap-3 pt-2">
                  <button
                    onClick={() => setCurrentPage('projects')}
                    className="flex items-center gap-2 px-5 py-3 rounded-lg font-semibold text-white text-sm transition"
                    style={{ backgroundColor: COLORS.blue }}
                  >
                    Découvrir nos projets <ChevronRight size={16} />
                  </button>
                  <button
                    onClick={() => setShowAppointmentForm(true)}
                    className="px-5 py-3 rounded-lg font-semibold text-sm transition border"
                    style={{ borderColor: COLORS.green, color: COLORS.greenDeep }}
                  >
                    Prendre rendez-vous
                  </button>
                </div>
              </div>
              <div className="md:col-span-2 rounded-2xl p-8" style={{ backgroundColor: COLORS.blueDeep }}>
                <p className="text-xs uppercase tracking-wide mb-6" style={{ color: '#8FB0BF' }}>En bref</p>
                <div className="space-y-5">
                  {[
                    { value: `${content.projects.length}`, label: 'Projets de recherche' },
                    { value: `${content.team.length}`, label: "Membres de l'équipe" },
                    { value: `${content.publications.length}`, label: 'Publications' },
                  ].map((s, i) => (
                    <div key={i} className="flex items-baseline justify-between pb-4" style={{ borderBottom: i < 2 ? '1px solid #2E5266' : 'none' }}>
                      <span className="cnrs-display text-3xl font-semibold text-white">{s.value}</span>
                      <span className="text-sm" style={{ color: '#AFC4CD' }}>{s.label}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="rounded-2xl p-8 md:p-10" style={{ backgroundColor: COLORS.greenSoft }}>
              <div className="md:flex justify-between items-center gap-8">
                <div>
                  <h2 className="cnrs-display text-2xl font-semibold mb-2" style={{ color: COLORS.greenDeep }}>
                    Une question, un projet à discuter ?
                  </h2>
                  <p style={{ color: COLORS.muted }}>Notre équipe répond à vos sollicitations sous quelques jours ouvrés.</p>
                </div>
                <button
                  onClick={() => setShowContactForm(true)}
                  className="mt-5 md:mt-0 px-6 py-3 rounded-lg font-semibold text-white text-sm whitespace-nowrap transition"
                  style={{ backgroundColor: COLORS.green }}
                >
                  Nous contacter
                </button>
              </div>
            </div>
          </div>
        )}

        {/* ---------------- ABOUT ---------------- */}
        {currentPage === 'about' && (
          <div className="max-w-3xl">
            <SectionHeading>À propos de CENARESSES</SectionHeading>
            <div className="space-y-5 text-base leading-relaxed" style={{ color: COLORS.ink }}>
              <p>
                Le Centre Africain de Recherches et d'Études en Sciences Sociales, Environnementales et de la Santé
                (CENARESSES) est un cabinet d'expertise basé à N'Djaména, spécialisé dans le renforcement des
                systèmes sanitaires et sociaux au Tchad.
              </p>
              <p>
                Nous accompagnons les institutions publiques, les partenaires techniques et financiers, les ONG et
                les acteurs privés dans la production d'analyses stratégiques et la mise en œuvre de solutions
                durables fondées sur des données probantes.
              </p>
              <p>
                Nous nous engageons à produire une connaissance scientifique rigoureuse, pertinente et
                transformatrice, au service des défis complexes du pays et de la région.
              </p>
              <h3 className="cnrs-display text-xl font-semibold pt-4" style={{ color: COLORS.blueDeep }}>Notre mission</h3>
              <p>Transformer les données en décisions stratégiques, les politiques en résultats concrets et les interventions en impact mesurable.</p>
              <h3 className="cnrs-display text-xl font-semibold pt-4" style={{ color: COLORS.blueDeep }}>Nos valeurs</h3>
              <ul className="space-y-2">
                {['Rigueur scientifique', 'Collaboration et partenariats', 'Intégrité et éthique', 'Innovation et excellence', 'Impact mesuré'].map((v) => (
                  <li key={v} className="flex items-center gap-2">
                    <span className="w-1.5 h-1.5 rounded-full flex-shrink-0" style={{ backgroundColor: COLORS.green }} />
                    {v}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {/* ---------------- PROJECTS ---------------- */}
        {currentPage === 'projects' && (
          <div>
            <SectionHeading>Nos projets de recherche</SectionHeading>
            {isAdmin && <AdminBar label="Projets" onAdd={() => openAddForm('project')} />}
            <div className="grid md:grid-cols-2 gap-6">
              {content.projects.map((project) => (
                <div key={project.id} className="rounded-xl p-6 bg-white" style={{ border: `1px solid ${COLORS.line}` }}>
                  <div className="text-4xl mb-4">{project.icon}</div>
                  <h3 className="cnrs-display text-lg font-semibold mb-2" style={{ color: COLORS.blueDeep }}>{project.title}</h3>
                  <p className="text-sm mb-4" style={{ color: COLORS.muted }}>{project.description}</p>
                  <Pill tone="green">{project.status}</Pill>
                  {isAdmin && (
                    <ItemAdminControls
                      onEdit={() => openEditForm('project', project)}
                      onDelete={() => handleDelete('project', project.id)}
                    />
                  )}
                </div>
              ))}
              {content.projects.length === 0 && <p style={{ color: COLORS.muted }}>Aucun projet publié pour le moment.</p>}
            </div>
          </div>
        )}

        {/* ---------------- PUBLICATIONS ---------------- */}
        {currentPage === 'publications' && (
          <div>
            <SectionHeading>Publications</SectionHeading>
            {isAdmin && <AdminBar label="Publications" onAdd={() => openAddForm('publication')} />}
            <div className="space-y-4">
              {content.publications.map((pub) => (
                <div key={pub.id} className="rounded-xl p-6 bg-white" style={{ border: `1px solid ${COLORS.line}` }}>
                  <div className="flex justify-between items-start gap-4">
                    <div className="flex-1">
                      <h3 className="cnrs-display text-lg font-semibold mb-1" style={{ color: COLORS.blueDeep }}>{pub.title}</h3>
                      <p className="text-sm mb-2" style={{ color: COLORS.muted }}>Par {pub.authors} · {pub.year}</p>
                      <Pill tone="blue">{pub.type}</Pill>
                    </div>
                    <button style={{ color: COLORS.blue }} title="Télécharger">
                      <Download size={20} />
                    </button>
                  </div>
                  {isAdmin && (
                    <ItemAdminControls
                      onEdit={() => openEditForm('publication', pub)}
                      onDelete={() => handleDelete('publication', pub.id)}
                    />
                  )}
                </div>
              ))}
              {content.publications.length === 0 && <p style={{ color: COLORS.muted }}>Aucune publication pour le moment.</p>}
            </div>
          </div>
        )}

        {/* ---------------- TEAM ---------------- */}
        {currentPage === 'team' && (
          <div>
            <SectionHeading>Notre équipe</SectionHeading>
            {isAdmin && <AdminBar label="Équipe" onAdd={() => openAddForm('team')} />}
            <div className="grid md:grid-cols-2 gap-6">
              {content.team.map((member) => (
                <div key={member.id} className="rounded-xl p-6 text-center bg-white" style={{ border: `1px solid ${COLORS.line}` }}>
                  <div className="text-5xl mb-3">{member.icon}</div>
                  <h3 className="cnrs-display text-lg font-semibold" style={{ color: COLORS.blueDeep }}>{member.name}</h3>
                  <p className="text-sm font-medium" style={{ color: COLORS.green }}>{member.role}</p>
                  <p className="text-sm" style={{ color: COLORS.muted }}>{member.speciality}</p>
                  {isAdmin && (
                    <div className="flex justify-center">
                      <ItemAdminControls
                        onEdit={() => openEditForm('team', member)}
                        onDelete={() => handleDelete('team', member.id)}
                      />
                    </div>
                  )}
                </div>
              ))}
              {content.team.length === 0 && <p style={{ color: COLORS.muted }}>Équipe à renseigner.</p>}
            </div>
          </div>
        )}

        {/* ---------------- NEWS ---------------- */}
        {currentPage === 'news' && (
          <div>
            <SectionHeading>Actualités</SectionHeading>
            {isAdmin && <AdminBar label="Actualités" onAdd={() => openAddForm('news')} />}
            <div className="space-y-5">
              {content.news.map((article) => (
                <div key={article.id} className="rounded-xl p-6 bg-white" style={{ border: `1px solid ${COLORS.line}` }}>
                  <div className="flex justify-between items-start gap-4 mb-2">
                    <h3 className="cnrs-display text-lg font-semibold flex-1" style={{ color: COLORS.blueDeep }}>{article.title}</h3>
                    <span className="text-xs whitespace-nowrap" style={{ color: COLORS.muted }}>{article.date}</span>
                  </div>
                  <p className="text-sm" style={{ color: COLORS.muted }}>{article.content}</p>
                  {isAdmin && (
                    <ItemAdminControls
                      onEdit={() => openEditForm('news', article)}
                      onDelete={() => handleDelete('news', article.id)}
                    />
                  )}
                </div>
              ))}
              {content.news.length === 0 && <p style={{ color: COLORS.muted }}>Aucune actualité publiée.</p>}
            </div>
          </div>
        )}

        {/* ---------------- RESOURCES ---------------- */}
        {currentPage === 'resources' && (
          <div>
            <SectionHeading>Ressources</SectionHeading>
            <div className="grid md:grid-cols-3 gap-6">
              {[
                { title: 'Méthodologie de recherche', icon: '📋', file: 'Guide_Methodologie.pdf' },
                { title: 'Guidelines éthiques', icon: '⚖️', file: 'Ethics_Guidelines.pdf' },
                { title: "Modèle d'article", icon: '📄', file: 'Article_Template.docx' },
              ].map((resource, i) => (
                <div key={i} className="rounded-xl p-6 text-center bg-white" style={{ border: `1px solid ${COLORS.line}` }}>
                  <div className="text-3xl mb-3">{resource.icon}</div>
                  <h3 className="font-semibold mb-1 text-sm">{resource.title}</h3>
                  <p className="text-xs mb-4" style={{ color: COLORS.muted }}>{resource.file}</p>
                  <button className="text-xs font-semibold flex items-center justify-center gap-2 w-full" style={{ color: COLORS.blue }}>
                    <Download size={14} /> Télécharger
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* FOOTER */}
      <footer style={{ backgroundColor: COLORS.blueDeep }} className="mt-10">
        <div className="max-w-6xl mx-auto px-5 py-12 grid md:grid-cols-4 gap-8">
          <div>
            <div className="flex items-center gap-3 mb-3">
              <div className="w-10 h-10 rounded-full bg-white p-0.5 flex-shrink-0">
                <img src={LOGO_DATA_URI} alt="Logo CENARESSES" className="w-full h-full rounded-full object-cover" />
              </div>
              <p className="cnrs-display text-white font-semibold">CENARESSES</p>
            </div>
            <p className="text-sm" style={{ color: '#AFC4CD' }}>
              Centre Africain de Recherches et d'Études en Sciences Sociales, Environnementales et de la Santé.
            </p>
          </div>
          <div>
            <p className="text-sm font-semibold text-white mb-3">Navigation</p>
            <ul className="space-y-2 text-sm" style={{ color: '#AFC4CD' }}>
              <li><button onClick={() => setCurrentPage('projects')}>Projets</button></li>
              <li><button onClick={() => setCurrentPage('publications')}>Publications</button></li>
              <li><button onClick={() => setCurrentPage('team')}>Équipe</button></li>
            </ul>
          </div>
          <div>
            <p className="text-sm font-semibold text-white mb-3">Contact</p>
            <ul className="space-y-2 text-sm" style={{ color: '#AFC4CD' }}>
              <li className="flex gap-2 items-center"><Mail size={14} /> info@cenaresses.org</li>
              <li className="flex gap-2 items-center"><Phone size={14} /> +235 68 52 62 48</li>
              <li className="flex gap-2 items-center"><MapPin size={14} /> N'Djaména, Tchad</li>
            </ul>
          </div>
          <div>
            <p className="text-sm font-semibold text-white mb-3">Nous solliciter</p>
            <button onClick={() => setShowAppointmentForm(true)} className="block text-sm mb-2" style={{ color: COLORS.green }}>Prendre rendez-vous</button>
            <button onClick={() => setShowContactForm(true)} className="block text-sm" style={{ color: COLORS.green }}>Nous écrire</button>
          </div>
        </div>
        <div className="text-center text-xs py-5" style={{ color: '#6E8791', borderTop: '1px solid #2E5266' }}>
          © 2026 CENARESSES. Tous droits réservés.
        </div>
      </footer>

      {/* ============== MODALS ============== */}

      {/* Connexion admin */}
      {showAdminLogin && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl p-8 max-w-sm w-full">
            <h3 className="cnrs-display text-xl font-semibold mb-1" style={{ color: COLORS.blueDeep }}>Espace administrateur</h3>
            <p className="text-sm mb-4" style={{ color: COLORS.muted }}>Réservé à l'équipe CENARESSES pour la mise à jour du site.</p>
            <form onSubmit={handleAdminLogin} className="space-y-3">
              <input
                type="password"
                placeholder="Mot de passe"
                value={adminPasswordInput}
                onChange={(e) => setAdminPasswordInput(e.target.value)}
                className={inputClass}
                style={inputStyle}
                autoFocus
              />
              {adminError && <p className="text-xs" style={{ color: '#B3453B' }}>{adminError}</p>}
              <div className="flex gap-3 pt-1">
                <button
                  type="submit"
                  disabled={adminBusy}
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-lg font-semibold text-white text-sm disabled:opacity-60"
                  style={{ backgroundColor: COLORS.blue }}
                >
                  {adminBusy && <Loader2 size={14} className="animate-spin" />}
                  {adminBusy ? 'Connexion…' : 'Se connecter'}
                </button>
                <button
                  type="button"
                  onClick={() => { setShowAdminLogin(false); setAdminError(''); setAdminPasswordInput(''); }}
                  className="flex-1 px-4 py-2 rounded-lg font-semibold text-sm border"
                  style={{ borderColor: COLORS.line }}
                >
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Contact */}
      {showContactForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl p-8 max-w-md w-full">
            <h3 className="cnrs-display text-xl font-semibold mb-4" style={{ color: COLORS.blueDeep }}>Nous contacter</h3>
            <form onSubmit={handleContactSubmit} className="space-y-3">
              <input type="text" placeholder="Nom" required className={inputClass} style={inputStyle} />
              <input type="email" placeholder="Email" required className={inputClass} style={inputStyle} />
              <textarea placeholder="Message" rows="4" required className={inputClass} style={inputStyle}></textarea>
              <div className="flex gap-3 pt-1">
                <button type="submit" className="flex-1 px-4 py-2 rounded-lg font-semibold text-white text-sm" style={{ backgroundColor: COLORS.blue }}>Envoyer</button>
                <button type="button" onClick={() => setShowContactForm(false)} className="flex-1 px-4 py-2 rounded-lg font-semibold text-sm border" style={{ borderColor: COLORS.line }}>Annuler</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Rendez-vous */}
      {showAppointmentForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl p-8 max-w-md w-full">
            <h3 className="cnrs-display text-xl font-semibold mb-4" style={{ color: COLORS.blueDeep }}>Prendre un rendez-vous</h3>
            <form onSubmit={handleAppointmentSubmit} className="space-y-3">
              <input type="text" name="name" placeholder="Nom complet" required className={inputClass} style={inputStyle} />
              <input type="email" name="email" placeholder="Email" required className={inputClass} style={inputStyle} />
              <input type="date" name="date" required className={inputClass} style={inputStyle} />
              <input type="time" name="time" required className={inputClass} style={inputStyle} />
              <input type="text" name="subject" placeholder="Sujet du rendez-vous" required className={inputClass} style={inputStyle} />
              <div className="flex gap-3 pt-1">
                <button type="submit" className="flex-1 px-4 py-2 rounded-lg font-semibold text-white text-sm" style={{ backgroundColor: COLORS.green }}>Confirmer</button>
                <button type="button" onClick={() => setShowAppointmentForm(false)} className="flex-1 px-4 py-2 rounded-lg font-semibold text-sm border" style={{ borderColor: COLORS.line }}>Annuler</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Formulaire admin générique (ajout / édition) */}
      {formType && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl p-8 max-w-md w-full max-h-[90vh] overflow-y-auto">
            <h3 className="cnrs-display text-xl font-semibold mb-4" style={{ color: COLORS.blueDeep }}>
              {editingItem ? 'Modifier' : 'Ajouter'} — {
                { project: 'un projet', publication: 'une publication', team: 'un membre', news: 'une actualité' }[formType]
              }
            </h3>
            <form onSubmit={handleFormSubmit} className="space-y-3">

              {formType === 'project' && (
                <>
                  <input name="title" placeholder="Titre du projet" defaultValue={editingItem?.title} required className={inputClass} style={inputStyle} />
                  <textarea name="description" placeholder="Description" rows="3" defaultValue={editingItem?.description} required className={inputClass} style={inputStyle}></textarea>
                  <input name="icon" placeholder="Emoji (ex: 📊)" defaultValue={editingItem?.icon} className={inputClass} style={inputStyle} />
                  <select name="status" defaultValue={editingItem?.status || 'En cours'} className={inputClass} style={inputStyle}>
                    <option>Planifié</option>
                    <option>En cours</option>
                    <option>Actif</option>
                    <option>Terminé</option>
                  </select>
                </>
              )}

              {formType === 'publication' && (
                <>
                  <input name="title" placeholder="Titre de la publication" defaultValue={editingItem?.title} required className={inputClass} style={inputStyle} />
                  <input name="authors" placeholder="Auteurs" defaultValue={editingItem?.authors} required className={inputClass} style={inputStyle} />
                  <input name="year" type="number" placeholder="Année" defaultValue={editingItem?.year} required className={inputClass} style={inputStyle} />
                  <input name="type" placeholder="Type (ex: Article de recherche)" defaultValue={editingItem?.type} required className={inputClass} style={inputStyle} />
                </>
              )}

              {formType === 'team' && (
                <>
                  <input name="name" placeholder="Nom complet" defaultValue={editingItem?.name} required className={inputClass} style={inputStyle} />
                  <input name="role" placeholder="Fonction" defaultValue={editingItem?.role} required className={inputClass} style={inputStyle} />
                  <input name="speciality" placeholder="Spécialité" defaultValue={editingItem?.speciality} required className={inputClass} style={inputStyle} />
                  <input name="icon" placeholder="Emoji (ex: 👤)" defaultValue={editingItem?.icon} className={inputClass} style={inputStyle} />
                </>
              )}

              {formType === 'news' && (
                <>
                  <input name="title" placeholder="Titre" defaultValue={editingItem?.title} required className={inputClass} style={inputStyle} />
                  <input name="date" type="date" defaultValue={editingItem?.date} required className={inputClass} style={inputStyle} />
                  <textarea name="content" placeholder="Contenu" rows="4" defaultValue={editingItem?.content} required className={inputClass} style={inputStyle}></textarea>
                </>
              )}

              <div className="flex gap-3 pt-2">
                <button type="submit" className="flex-1 px-4 py-2 rounded-lg font-semibold text-white text-sm" style={{ backgroundColor: COLORS.green }}>
                  {editingItem ? 'Enregistrer' : 'Ajouter'}
                </button>
                <button type="button" onClick={closeForm} className="flex-1 px-4 py-2 rounded-lg font-semibold text-sm border" style={{ borderColor: COLORS.line }}>
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
